import React from "react";

export function LandingPage6() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Industrial Foams Pvt. Ltd. — Premium PUF Panel Manufacturer in India</title>
    <link href="https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800&family=Barlow:wght@400;500;600&display=swap" rel="stylesheet">
    <style>
        *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

        :root {
            --navy: #0B1E3A;
            --navy-mid: #112444;
            --navy-dark: #070F1E;
            --charcoal: #1C2A3A;
            --orange: #F47B20;
            --orange-dark: #D9660E;
            --white: #FFFFFF;
            --off-white: #F4F6F8;
            --gray-light: #E8ECF0;
            --gray-mid: #9AAAB8;
            --text-dark: #0B1E3A;
            --text-body: #2D3E50;
            --font-head: 'Barlow Condensed', sans-serif;
            --font-body: 'Barlow', sans-serif;
        }

        html { scroll-behavior: smooth; }

        body {
            font-family: var(--font-body);
            color: var(--text-body);
            background: var(--white);
            line-height: 1.6;
            font-size: 16px;
        }

        header {
            background: var(--navy-dark);
            padding: 0 5%;
            display: flex;
            align-items: center;
            justify-content: space-between;
            height: 64px;
            position: sticky;
            top: 0;
            z-index: 100;
            border-bottom: 2px solid var(--orange);
        }

        .logo {
            font-family: var(--font-head);
            font-weight: 800;
            font-size: 22px;
            color: var(--white);
            letter-spacing: 0.5px;
        }
        .logo span { color: var(--orange); }

        nav { display: flex; gap: 28px; align-items: center; }
        nav a {
            font-family: var(--font-head);
            font-size: 15px;
            font-weight: 600;
            letter-spacing: 0.5px;
            color: rgba(255,255,255,0.7);
            text-decoration: none;
            text-transform: uppercase;
            transition: color 0.2s;
        }
        nav a:hover { color: var(--orange); }

        .header-cta {
            background: var(--orange);
            color: var(--white);
            font-family: var(--font-head);
            font-weight: 700;
            font-size: 15px;
            letter-spacing: 0.8px;
            text-transform: uppercase;
            padding: 9px 22px;
            border: none;
            cursor: pointer;
            text-decoration: none;
        }
        .header-cta:hover { background: var(--orange-dark); }

        .hero {
            background: var(--navy-dark);
            min-height: 100vh;
            display: flex;
            align-items: stretch;
            position: relative;
            overflow: hidden;
        }

        .hero-bg-image {
            position: absolute;
            inset: 0;
            background-image: url('https://images.unsplash.com/photo-1504307651254-35680f356dfd?w=1600&q=80');
            background-size: cover;
            background-position: center;
            opacity: 0.18;
        }

        .hero-overlay {
            position: absolute;
            inset: 0;
            background: linear-gradient(105deg, rgba(7,15,30,0.98) 0%, rgba(11,30,58,0.92) 55%, rgba(11,30,58,0.4) 100%);
        }

        .hero-inner {
            position: relative;
            z-index: 2;
            max-width: 1280px;
            margin: 0 auto;
            width: 100%;
            padding: 80px 5% 60px;
            display: grid;
            grid-template-columns: 1.1fr 0.9fr;
            gap: 60px;
            align-items: center;
        }

        .hero-eyebrow {
            font-family: var(--font-head);
            font-size: 12px;
            font-weight: 600;
            letter-spacing: 3.5px;
            text-transform: uppercase;
            color: var(--orange);
            margin-bottom: 18px;
            display: flex;
            align-items: center;
            gap: 10px;
        }
        .hero-eyebrow::before {
            content: '';
            width: 28px;
            height: 2px;
            background: var(--orange);
            display: block;
        }

        .hero-h1 {
            font-family: var(--font-head);
            font-weight: 800;
            font-size: clamp(44px, 5.5vw, 72px);
            line-height: 0.97;
            color: var(--white);
            text-transform: uppercase;
            letter-spacing: -1px;
            margin-bottom: 24px;
        }
        .hero-h1 em { color: var(--orange); font-style: normal; }

        .hero-sub {
            font-size: 17px;
            color: rgba(255,255,255,0.65);
            line-height: 1.7;
            margin-bottom: 36px;
            max-width: 520px;
        }

        .trust-row {
            display: flex;
            gap: 28px;
            padding-top: 28px;
            border-top: 1px solid rgba(255,255,255,0.1);
            flex-wrap: wrap;
        }

        .trust-item {
            text-align: center;
        }
        .trust-num {
            font-family: var(--font-head);
            font-size: 30px;
            font-weight: 800;
            color: var(--orange);
            display: block;
            line-height: 1;
        }
        .trust-lbl {
            font-size: 12px;
            color: rgba(255,255,255,0.5);
            letter-spacing: 0.3px;
        }
        .trust-divider {
            width: 1px;
            background: rgba(255,255,255,0.12);
            align-self: stretch;
        }

        .hero-form-wrap {
            background: var(--white);
            padding: 36px 32px 32px;
            position: relative;
        }
        .hero-form-wrap::before {
            content: '';
            position: absolute;
            top: 0; left: 0; right: 0;
            height: 4px;
            background: var(--orange);
        }

        .hf-title {
            font-family: var(--font-head);
            font-size: 22px;
            font-weight: 800;
            color: var(--navy);
            text-transform: uppercase;
            letter-spacing: 0.3px;
            margin-bottom: 4px;
        }
        .hf-sub {
            font-size: 13px;
            color: #6B7E8E;
            margin-bottom: 22px;
            padding-bottom: 18px;
            border-bottom: 1px solid var(--gray-light);
        }

        .field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
        .field-group { margin-bottom: 14px; }
        .field-group label {
            display: block;
            font-size: 11px;
            font-weight: 600;
            letter-spacing: 1px;
            text-transform: uppercase;
            color: #7A8E9E;
            margin-bottom: 5px;
        }
        .field-group input,
        .field-group select,
        .field-group textarea {
            width: 100%;
            padding: 11px 13px;
            border: 1.5px solid var(--gray-light);
            font-family: var(--font-body);
            font-size: 14px;
            color: var(--navy);
            background: var(--white);
            outline: none;
            transition: border-color 0.2s;
            border-radius: 0;
            -webkit-appearance: none;
        }
        .field-group input:focus,
        .field-group select:focus,
        .field-group textarea:focus { border-color: var(--orange); }
        .field-group textarea { height: 68px; resize: none; }

        .form-submit {
            width: 100%;
            background: var(--orange);
            color: var(--white);
            font-family: var(--font-head);
            font-weight: 700;
            font-size: 17px;
            letter-spacing: 1px;
            text-transform: uppercase;
            padding: 15px;
            border: none;
            cursor: pointer;
            transition: background 0.2s;
            margin-top: 4px;
        }
        .form-submit:hover { background: var(--orange-dark); }
        .form-note {
            text-align: center;
            font-size: 11px;
            color: #A0B0BC;
            margin-top: 10px;
        }

        section { padding: 80px 5%; }
        .section-inner { max-width: 1200px; margin: 0 auto; }

        .section-tag {
            font-family: var(--font-head);
            font-size: 11px;
            letter-spacing: 3.5px;
            text-transform: uppercase;
            color: var(--orange);
            font-weight: 700;
            margin-bottom: 12px;
            display: flex;
            align-items: center;
            gap: 10px;
        }
        .section-tag::before {
            content: '';
            width: 20px;
            height: 2px;
            background: var(--orange);
            display: block;
        }

        .section-h2 {
            font-family: var(--font-head);
            font-weight: 800;
            font-size: clamp(32px, 4vw, 52px);
            text-transform: uppercase;
            color: var(--navy);
            line-height: 1.0;
            margin-bottom: 14px;
            letter-spacing: -0.3px;
        }
        .section-h2 em { color: var(--orange); font-style: normal; }

        .section-lead {
            font-size: 17px;
            color: #4A6070;
            max-width: 560px;
            line-height: 1.7;
            margin-bottom: 48px;
        }

        .marquee-strip {
            background: var(--orange);
            overflow: hidden;
            padding: 14px 0;
            white-space: nowrap;
        }
        .marquee-track {
            display: inline-flex;
            animation: marquee 28s linear infinite;
        }

        .marquee-item {
            font-family: var(--font-head);
            font-size: 14px;
            font-weight: 700;
            letter-spacing: 2px;
            text-transform: uppercase;
            color: rgba(255,255,255,0.9);
            padding: 0 32px;
        }
        .marquee-dot {
            color: rgba(255,255,255,0.4);
            padding: 0 4px;
        }
        @keyframes marquee {
            from { transform: translateX(0); }
            to { transform: translateX(-50%); }
        }

        .problems-bg { background: var(--off-white); }

        .problems-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 20px;
        }
        .problem-card {
            background: var(--white);
            border-left: 3px solid var(--navy);
            padding: 28px 28px 24px;
        }
        .problem-num {
            font-family: var(--font-head);
            font-size: 52px;
            font-weight: 800;
            color: var(--gray-light);
            line-height: 1;
            margin-bottom: 10px;
        }
        .problem-title {
            font-family: var(--font-head);
            font-size: 21px;
            font-weight: 700;
            color: var(--navy);
            text-transform: uppercase;
            letter-spacing: 0.3px;
            margin-bottom: 10px;
        }
        .problem-desc { font-size: 15px; color: #5A6E7E; line-height: 1.65; }

        .solution-wrap {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 48px;
            align-items: center;
        }
        .solution-image-col { position: relative; }
        .solution-main-img {
            width: 100%;
            height: 480px;
            object-fit: cover;
            display: block;
        }
        .solution-img-badge {
            position: absolute;
            bottom: -1px;
            left: -1px;
            background: var(--orange);
            padding: 16px 24px;
        }
        .sib-num {
            font-family: var(--font-head);
            font-size: 36px;
            font-weight: 800;
            color: var(--white);
            line-height: 1;
            display: block;
        }
        .sib-lbl {
            font-size: 12px;
            color: rgba(255,255,255,0.8);
            letter-spacing: 0.5px;
        }

        .solution-cards { display: grid; gap: 0; border: 1px solid var(--gray-light); }
        .solution-item {
            padding: 28px 32px;
            border-bottom: 1px solid var(--gray-light);
            transition: background 0.2s;
        }
        .solution-item:last-child { border-bottom: none; }
        .solution-item:hover { background: #F8FAFC; }
        .sol-header { display: flex; align-items: center; gap: 14px; margin-bottom: 10px; }
        .sol-num {
            font-family: var(--font-head);
            font-size: 13px;
            font-weight: 700;
            color: var(--orange);
            letter-spacing: 1px;
            min-width: 28px;
        }
        .sol-title {
            font-family: var(--font-head);
            font-size: 19px;
            font-weight: 700;
            color: var(--navy);
            text-transform: uppercase;
        }
        .sol-badge {
            display: inline-block;
            background: rgba(244,123,32,0.1);
            color: var(--orange-dark);
            font-family: var(--font-head);
            font-size: 12px;
            font-weight: 700;
            letter-spacing: 0.5px;
            padding: 3px 10px;
            text-transform: uppercase;
            margin-left: auto;
            flex-shrink: 0;
        }
        .sol-desc { font-size: 14px; color: #5A6E7E; line-height: 1.6; }

        .benefits-bg { background: var(--navy); }
        .benefits-bg .section-h2 { color: var(--white); }
        .benefits-bg .section-lead { color: rgba(255,255,255,0.55); }

        .benefits-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 1px;
            background: rgba(255,255,255,0.07);
        }
        .benefit-card {
            background: var(--navy);
            padding: 32px 24px;
            text-align: center;
            transition: background 0.2s;
        }
        .benefit-card:hover { background: var(--navy-mid); }
        .benefit-num {
            font-family: var(--font-head);
            font-size: 38px;
            font-weight: 800;
            color: var(--orange);
            display: block;
            line-height: 1;
            margin-bottom: 6px;
        }
        .benefit-title {
            font-family: var(--font-head);
            font-size: 16px;
            font-weight: 700;
            color: var(--white);
            text-transform: uppercase;
            letter-spacing: 0.3px;
            margin-bottom: 10px;
        }
        .benefit-desc { font-size: 13px; color: rgba(255,255,255,0.45); line-height: 1.6; }

        .use-cases-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 16px;
        }
        .use-case-card {
            position: relative;
            height: 300px;
            overflow: hidden;
            cursor: pointer;
        }
        .uc-img {
            position: absolute;
            inset: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.5s ease;
        }
        .use-case-card:hover .uc-img { transform: scale(1.06); }
        .uc-overlay {
            position: absolute;
            bottom: 0; left: 0; right: 0;
            background: linear-gradient(to top, rgba(7,15,30,0.95) 0%, rgba(7,15,30,0.5) 60%, transparent 100%);
            padding: 36px 28px 24px;
        }
        .uc-tag {
            font-family: var(--font-head);
            font-size: 10px;
            letter-spacing: 3px;
            text-transform: uppercase;
            color: var(--orange);
            font-weight: 700;
            display: block;
            margin-bottom: 4px;
        }
        .uc-title {
            font-family: var(--font-head);
            font-size: 26px;
            font-weight: 800;
            color: var(--white);
            text-transform: uppercase;
            line-height: 1.05;
            margin-bottom: 4px;
        }
        .uc-desc { font-size: 13px; color: rgba(255,255,255,0.6); }

        .image-showcase {
            display: grid;
            grid-template-columns: 1.4fr 1fr 1fr;
            gap: 12px;
            height: 380px;
            margin-bottom: 48px;
        }
        .showcase-img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            display: block;
        }
        .showcase-tall { grid-row: span 1; }

        .proof-bg { background: var(--off-white); }

        .proof-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 20px;
            margin-bottom: 40px;
        }
        .proof-card {
            background: var(--white);
            padding: 0;
            border-top: 3px solid var(--orange);
            overflow: hidden;
        }
        .proof-img {
            width: 100%;
            height: 180px;
            object-fit: cover;
            display: block;
        }
        .proof-body { padding: 20px 22px 22px; }
        .proof-industry {
            font-family: var(--font-head);
            font-size: 10px;
            letter-spacing: 2.5px;
            text-transform: uppercase;
            color: var(--orange);
            font-weight: 700;
            margin-bottom: 6px;
        }
        .proof-project {
            font-family: var(--font-head);
            font-size: 18px;
            font-weight: 700;
            color: var(--navy);
            text-transform: uppercase;
            margin-bottom: 8px;
            line-height: 1.1;
        }
        .proof-detail { font-size: 13px; color: #5A6E7E; line-height: 1.6; }
        .proof-metric {
            margin-top: 14px;
            padding-top: 14px;
            border-top: 1px solid var(--gray-light);
            display: flex;
            gap: 20px;
        }
        .pm-val {
            font-family: var(--font-head);
            font-size: 20px;
            font-weight: 700;
            color: var(--orange);
            display: block;
        }
        .pm-lbl { font-size: 10px; color: #9AAAB8; }

        .client-strip {
            background: var(--white);
            border: 1px solid var(--gray-light);
            padding: 28px 40px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 20px;
            flex-wrap: wrap;
        }
        .client-strip-label {
            font-family: var(--font-head);
            font-size: 11px;
            letter-spacing: 2px;
            text-transform: uppercase;
            color: #9AAAB8;
            flex-shrink: 0;
        }
        .client-logos { display: flex; gap: 40px; align-items: center; flex-wrap: wrap; }
        .client-name {
            font-family: var(--font-head);
            font-size: 17px;
            font-weight: 700;
            color: #B0C0CC;
            letter-spacing: 0.5px;
            text-transform: uppercase;
        }

        .form-section {
            background: var(--charcoal);
            background-image: linear-gradient(135deg, #1C2A3A 0%, #0B1E3A 100%);
        }
        .form-inner {
            max-width: 1000px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 60px;
            align-items: center;
        }
        .form-left .section-h2 { color: var(--white); }
        .form-promise { font-size: 15px; color: rgba(255,255,255,0.5); line-height: 1.7; margin-bottom: 28px; }
        .form-features { list-style: none; }
        .form-features li {
            font-size: 14px;
            color: rgba(255,255,255,0.65);
            padding: 9px 0;
            border-bottom: 1px solid rgba(255,255,255,0.07);
            display: flex;
            align-items: center;
            gap: 10px;
        }
        .form-features li::before {
            content: '';
            width: 5px;
            height: 5px;
            background: var(--orange);
            display: block;
            flex-shrink: 0;
        }
        .lead-form { background: var(--white); padding: 36px 32px; }
        .form-title {
            font-family: var(--font-head);
            font-size: 20px;
            font-weight: 700;
            color: var(--navy);
            text-transform: uppercase;
            margin-bottom: 24px;
            padding-bottom: 14px;
            border-bottom: 2px solid var(--orange);
        }

        .final-cta {
            background: var(--orange);
            padding: 80px 5%;
            text-align: center;
            position: relative;
            overflow: hidden;
        }
        .final-cta::before {
            content: '';
            position: absolute;
            inset: 0;
            background-image: url('https://images.unsplash.com/photo-1504307651254-35680f356dfd?w=1200&q=60');
            background-size: cover;
            background-position: center;
            opacity: 0.08;
        }
        .final-cta-h2 {
            font-family: var(--font-head);
            font-weight: 800;
            font-size: clamp(32px, 5vw, 58px);
            color: var(--white);
            text-transform: uppercase;
            letter-spacing: -0.3px;
            margin-bottom: 14px;
            line-height: 1.0;
            position: relative;
        }
        .final-cta-sub {
            font-size: 17px;
            color: rgba(255,255,255,0.85);
            margin-bottom: 36px;
            position: relative;
        }
        .btn-white {
            background: var(--white);
            color: var(--orange);
            font-family: var(--font-head);
            font-weight: 800;
            font-size: 17px;
            letter-spacing: 1px;
            text-transform: uppercase;
            padding: 15px 40px;
            border: none;
            cursor: pointer;
            text-decoration: none;
            display: inline-block;
            margin: 0 8px;
            position: relative;
        }
        .btn-white:hover { background: var(--off-white); }
        .btn-dark {
            background: var(--navy-dark);
            color: var(--white);
            font-family: var(--font-head);
            font-weight: 800;
            font-size: 17px;
            letter-spacing: 1px;
            text-transform: uppercase;
            padding: 15px 40px;
            border: none;
            cursor: pointer;
            text-decoration: none;
            display: inline-block;
            margin: 0 8px;
            position: relative;
        }

        footer {
            background: var(--navy-dark);
            padding: 40px 5%;
            border-top: 2px solid var(--orange);
        }
        .footer-inner {
            max-width: 1200px;
            margin: 0 auto;
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;
            gap: 20px;
        }
        .footer-logo { font-family: var(--font-head); font-size: 20px; font-weight: 800; color: var(--white); }
        .footer-logo span { color: var(--orange); }
        .footer-contacts { display: flex; gap: 28px; flex-wrap: wrap; }
        .footer-contact-item {
            display: flex;
            align-items: center;
            gap: 8px;
            font-size: 14px;
            color: rgba(255,255,255,0.65);
            text-decoration: none;
        }
        .footer-contact-item svg { width: 15px; height: 15px; fill: var(--orange); }
        .footer-copy {
            font-size: 12px;
            color: rgba(255,255,255,0.28);
            width: 100%;
            text-align: center;
            margin-top: 20px;
            padding-top: 20px;
            border-top: 1px solid rgba(255,255,255,0.07);
        }

        .sticky-mobile-bar {
            display: none;
            position: fixed;
            bottom: 0; left: 0; right: 0;
            background: var(--navy-dark);
            border-top: 2px solid var(--orange);
            z-index: 1000;
            padding: 10px 16px;
            gap: 10px;
        }
        .sticky-mobile-bar a {
            flex: 1;
            text-align: center;
            padding: 12px 8px;
            font-family: var(--font-head);
            font-size: 15px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            text-decoration: none;
